BEGIN;
CREATE TABLE contract_semantics_versions (market_ticker text REFERENCES markets(ticker), version integer NOT NULL, rules_hash text NOT NULL, semantics_hash text NOT NULL, approval text NOT NULL, question text NOT NULL, yes_meaning text NOT NULL, no_meaning text NOT NULL, authority text NOT NULL, deadline timestamptz NOT NULL, timezone text NOT NULL, comparator text NOT NULL, threshold numeric, unit text, rounding text, revision_policy text, recount_policy text, cancellation_policy text, postponement_policy text, early_close_condition text, exceptions jsonb NOT NULL, parser_name text NOT NULL, parser_version text NOT NULL, created_at timestamptz NOT NULL, invalidated_at timestamptz, PRIMARY KEY(market_ticker,version), UNIQUE(market_ticker,semantics_hash));
CREATE TABLE contract_semantics_sources (market_ticker text NOT NULL, semantics_version integer NOT NULL, source_name text NOT NULL, source_url text, authority text NOT NULL, is_primary boolean NOT NULL, content_hash text, observed_at timestamptz NOT NULL, PRIMARY KEY(market_ticker,semantics_version,source_name), FOREIGN KEY(market_ticker,semantics_version) REFERENCES contract_semantics_versions(market_ticker,version));
CREATE TABLE contract_interpretation_issues (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, market_ticker text NOT NULL REFERENCES markets(ticker), rules_hash text NOT NULL, issue_code text NOT NULL, detail text NOT NULL, detected_at timestamptz NOT NULL, resolved_at timestamptz);
COMMIT;
